class Solution {
    long long MOD = 1000000007;

    long long power(long long base, long long exp) {
        long long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }

public:
    int magicalSum(int m, int k, std::vector<int>& nums) {
        std::vector<std::vector<int>> comb(m + 1, std::vector<int>(m + 1, 0));
        for (int i = 0; i <= m; ++i) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
            }
        }

        std::map<std::tuple<int, int, int, int>, int> memo;

        auto dp = [&](auto& self, int leftM, int leftK, int i, int carry) -> int {
            int bits = __builtin_popcount(carry);
            if (leftM < 0 || leftK < 0 || (bits + leftM < leftK)) return 0;
            if (leftM == 0) return leftK == bits ? 1 : 0;
            if (i == (int)nums.size()) return 0;

            auto key = std::make_tuple(leftM, leftK, i, carry);
            if (memo.count(key)) return memo[key];

            long long res = 0;
            for (int t = 0; t <= leftM; ++t) {
                long long ways = comb[leftM][t];
                long long prod = power(nums[i], t);
                int nCarry = (carry + t) >> 1;
                int nBits = (carry + t) & 1;
                long long sub = self(self, leftM - t, leftK - nBits, i + 1, nCarry);
                res = (res + (ways * prod % MOD) * sub) % MOD;
            }
            return memo[key] = res;
        };

        return dp(dp, m, k, 0, 0);
    }
};

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;
    private int[][] comb;
    private Map<String, Integer> memo;

    public int magicalSum(int m, int k, int[] nums) {
        comb = new int[m + 1][m + 1];
        for (int i = 0; i <= m; ++i) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
            }
        }
        memo = new HashMap<>();
        return dp(m, k, 0, 0, nums);
    }

    private int dp(int leftM, int leftK, int i, int carry, int[] nums) {
        int bits = Integer.bitCount(carry);
        if (leftM < 0 || leftK < 0 || (bits + leftM < leftK)) return 0;
        if (leftM == 0) return leftK == bits ? 1 : 0;
        if (i == nums.length) return 0;

        String key = leftM + "," + leftK + "," + i + "," + carry;
        if (memo.containsKey(key)) return memo.get(key);

        long res = 0;
        for (int t = 0; t <= leftM; ++t) {
            long ways = comb[leftM][t];
            long prod = power(nums[i], t);
            int nCarry = (carry + t) >> 1;
            int nBits = (carry + t) & 1;
            long sub = dp(leftM - t, leftK - nBits, i + 1, nCarry, nums);
            res = (res + (ways * prod % MOD) * sub) % MOD;
        }
        memo.put(key, (int) res);
        return (int) res;
    }

    private long power(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }
}

