var magicalSum = function(m, k, nums) {
    const MOD = 1000000007n;
    const comb = Array.from({ length: m + 1 }, () => new Array(m + 1).fill(0n));
    for (let i = 0; i <= m; ++i) {
        comb[i][0] = 1n;
        for (let j = 1; j <= i; ++j) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
        }
    }

    const memo = new Map();

    function power(base, exp) {
        let res = 1n;
        base = BigInt(base) % MOD;
        exp = BigInt(exp);
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }

    function popcount(x) {
        let cnt = 0;
        while (x > 0) {
            cnt += x & 1;
            x >>= 1;
        }
        return cnt;
    }

    function dp(leftM, leftK, i, carry) {
        const bits = popcount(carry);
        if (leftM < 0 || leftK < 0 || (bits + leftM < leftK)) return 0n;
        if (leftM === 0) return leftK === bits ? 1n : 0n;
        if (i === nums.length) return 0n;

        const key = `${leftM},${leftK},${i},${carry}`;
        if (memo.has(key)) return memo.get(key);

        let res = 0n;
        for (let t = 0; t <= leftM; ++t) {
            const ways = comb[leftM][t];
            const prod = power(nums[i], t);
            const nCarry = (carry + t) >> 1;
            const nBits = (carry + t) & 1;
            const sub = dp(leftM - t, leftK - nBits, i + 1, nCarry);
            res = (res + (ways * prod % MOD) * sub) % MOD;
        }
        memo.set(key, res);
        return res;
    }

    return Number(dp(m, k, 0, 0));
};
